export const environmentSource = {
  "packages/provider-opencode/src/server/driver.ts": "import * as Deferred from \"effect/Deferred\";\nimport * as Stream from \"effect/Stream\";\n    const listOpenCode2Workspace = (cwd: string) =>\n      openCode2Server.withConnection(({ client, events }) =>\n        Effect.gen(function* () {\n          // OpenCode names a location by its resolved path (no trailing slash or `..`).\n          const directory = pathService.resolve(cwd);\n          const location = { directory };\n          const scanned = yield* Deferred.make<void>();\n          const pending = new Set([\"command.updated\", \"skill.updated\"]);\n          const stream = yield* events.pipe(Effect.option);\n          if (stream._tag === \"Some\") {\n            yield* stream.value.pipe(\n              Stream.runForEach((event) =>\n                \"location\" in event &&\n                event.location?.directory === directory &&\n                pending.delete(event.type) &&\n                pending.size === 0\n                  ? Deferred.succeed(scanned, undefined)\n                  : Effect.void,\n              ),\n              Effect.ignore,\n              Effect.forkScoped,\n            );\n          }\n          return yield* loadOpenCode2Workspace(\n            Effect.all(\n              {\n                skills: client.skill.list({ location }).pipe(Effect.map((list) => list.data)),\n                commands: client.command.list({ location }).pipe(Effect.map((list) => list.data)),\n              },\n              { concurrency: \"unbounded\" },\n            ),\n            Deferred.await(scanned),\n            // Without events no scan can be awaited, so trust the first read as before.\n            stream._tag === \"None\"\n              ? Effect.succeed(true)\n              : client.debug.location.list().pipe(\n                  Effect.map((loaded) => loaded.some((entry) => entry.directory === directory)),\n                  Effect.timeout(\"2 seconds\"),\n                  Effect.orElseSucceed(() => true),\n                ),\n            // OpenCode answers provider.list for a location only once its skill scan has ended.\n            client.provider.list({ location }).pipe(Effect.timeout(\"10 seconds\"), Effect.ignore),\n            processEnv,\n          );\n        }).pipe(Effect.scoped),\n      );\n",
  "packages/provider-opencode/src/server/status.ts": "/**\n * Reading a location the server has not loaded boots its scan, and only reads after the scan's\n * `command.updated` plus `skill.updated` are complete; `scanned` must listen before `read`. A\n * loaded location listing no commands is still scanning. A location another caller booted\n * moments earlier lists as loaded with only built-ins, so `settled` waits out its scan first.\n */\nexport const loadOpenCode2Workspace = Effect.fn(\"OpencodeProviderStatus.loadOpenCode2Workspace\")(\n  function* <E>(\n    read: Effect.Effect<OpenCode2Workspace, E>,\n    scanned: Effect.Effect<void>,\n    loaded: Effect.Effect<boolean>,\n    settled: Effect.Effect<void> = Effect.void,\n    environment?: NodeJS.ProcessEnv,\n  ) {\n    const wasLoaded = yield* loaded;\n    yield* settled;\n    const first = yield* read;\n    if (wasLoaded && first.commands.length > 0) return first;\n    yield* scanned.pipe(\n      Effect.timeoutOption(resolveProviderProbeTimeoutMs(\"opencode\", 10_000, environment)),\n    );\n    return yield* read;\n  },\n);\n\n"
};
